public class HarvestJobFactory(string resourceName = null, Action<Humidifier.MediaPackageV2.HarvestJob> factoryAction = null) : ResourceFactory<Humidifier.MediaPackageV2.HarvestJob>(resourceName)
{

    internal InnerHarvestJobDestinationFactory DestinationFactory { get; set; }

    internal InnerHarvestJobHarvesterScheduleConfigurationFactory ScheduleConfigurationFactory { get; set; }

    internal InnerHarvestJobHarvestedManifestsFactory HarvestedManifestsFactory { get; set; }

    protected override Humidifier.MediaPackageV2.HarvestJob Create()
    {
        var harvestJobResult = CreateHarvestJob();
        factoryAction?.Invoke(harvestJobResult);

        return harvestJobResult;
    }

    private Humidifier.MediaPackageV2.HarvestJob CreateHarvestJob()
    {
        var harvestJobResult = new Humidifier.MediaPackageV2.HarvestJob
        {
            GivenName = InputResourceName,
        };

        return harvestJobResult;
    }
    public override void CreateChildren(Humidifier.MediaPackageV2.HarvestJob result)
    {
        base.CreateChildren(result);

        result.Destination ??= DestinationFactory?.Build();
        result.ScheduleConfiguration ??= ScheduleConfigurationFactory?.Build();
        result.HarvestedManifests ??= HarvestedManifestsFactory?.Build();
    }

} // End Of Class

